import type { SparkLesson } from "@/lib/spark-lessons";
import type { ExecutionKind } from "@/lib/airflow-execution";

export const AIRFLOW_VERSION="3.1";
export const airflowDocs="https://airflow.apache.org/docs/apache-airflow/3.1.0/";
type Question=SparkLesson["quiz"][number];
export type AirflowVisual="execution"|"architecture"|"schedule"|"catchup"|"xcom"|"config"|"monitoring"|"production";
export interface AirflowLesson extends SparkLesson {visual:AirflowVisual;execution?:ExecutionKind;takeaway:string;resource:string;decision:Question;setup:string;codeKind:"Complete teaching DAG"|"Configuration fragment"|"Task fragment";}
const q=(question:string,options:string[],correct:number,explanation:string):Question=>({question,options,correct,explanation});
const wrap=(id:string,body:string,imports="",schedule="None",catchup=false)=>`import pendulum\nfrom airflow.sdk import dag, task\n${imports?imports+"\n":""}\n@dag(\n    dag_id="dataprep_${id}",\n    start_date=pendulum.datetime(2026, 1, 1, tz="UTC"),\n    schedule=${schedule},\n    catchup=${catchup?"True":"False"},\n)\ndef pipeline():\n${body.split("\n").map(line=>"    "+line).join("\n")}\n\npipeline()`;
const chainBody=`@task\ndef stage(label: str):\n    print(f"Teaching stage: {label}")\n\nextract = stage.override(task_id="extract")("extract")\ntransform = stage.override(task_id="transform")("transform")\nload = stage.override(task_id="load")("load")\nextract >> transform >> load`;
const chainCode=wrap("chain",chainBody);
const forkCode=wrap("dependencies",`@task\ndef stage(label: str):\n    print(label)\n\nextract = stage.override(task_id="extract")("extract")\nvalidate = stage.override(task_id="validate")("validate")\nenrich = stage.override(task_id="enrich")("enrich")\nload = stage.override(task_id="load")("load")\nextract >> [validate, enrich]\n[validate, enrich] >> load`);
const intervalCode=wrap("daily_sales",`@task\ndef inspect_interval():\n    context = get_current_context()\n    print(context["data_interval_start"])\n    print(context["data_interval_end"])\n\ninspect_interval()`,`from airflow.sdk import get_current_context\nfrom airflow.timetables.interval import CronDataIntervalTimetable`,`CronDataIntervalTimetable("0 2 * * *", timezone="UTC")`);
const retryCode=wrap("retry",`@task\ndef extract():\n    return 150\n\n@task(retries=1, retry_delay=timedelta(minutes=5))\ndef transform(total: int):\n    context = get_current_context()\n    if context["ti"].try_number == 1:\n        raise RuntimeError("Teaching-only transient failure")\n    return total\n\n@task\ndef load(total: int):\n    print(f"Validated total: {total}")\n\nload(transform(extract()))`,`from datetime import timedelta\nfrom airflow.sdk import get_current_context`);
const finalCode=wrap("sales_practice",`@task\ndef extract():\n    # Tiny teaching payload; use storage references for real datasets.\n    return [{"order_id": 501, "amount": 100}, {"order_id": 502, "amount": 50}]\n\n@task\ndef validate(rows: list):\n    if not all(row["amount"] > 0 for row in rows):\n        raise ValueError("Non-positive sale amount")\n    if len({row["order_id"] for row in rows}) != len(rows):\n        raise ValueError("Duplicate order identity")\n    return rows\n\n@task\ndef transform(rows: list):\n    return sum(row["amount"] for row in rows)\n\n@task\ndef load(total: int):\n    # Teaching stand-in: no external warehouse write occurs.\n    print(f"Would publish total={total}")\n    return total\n\n@task\ndef quality_check(total: int):\n    if total != 150:\n        raise ValueError("Teaching fixture total should be 150")\n\nquality_check(load(transform(validate(extract()))))`);
interface Spec {id:string;title:string;visual:AirflowVisual;execution?:ExecutionKind;idea:string;why:string;remember:string;takeaway:string;code:string;output:string;steps:string[];decision:Question;hint:string;solution:string;interview:[string,string,string];mistakes:[string,string,string,string,string][];quiz:Question[];doc:string;setup?:string;codeKind?:AirflowLesson["codeKind"]}
const specs:Spec[]=[
  {id:"introduction",title:"Airflow Introduction",visual:"execution",execution:"chain",
    idea:"Airflow coordinates workflows: dependencies, schedules, retries and task state. A sales pipeline may extract, validate, transform, load and then check quality. Airflow makes the ordering and operational history explicit.",
    why:"A failed extraction should not silently feed a warehouse load. Orchestration connects the work and exposes what ran, what failed and what must wait.",remember:"Airflow is not a streaming engine. It can run task code or submit work to another system; heavy processing can live in Spark or a warehouse.",takeaway:"Define the workflow, create runs, execute eligible tasks and track their outcomes.",code:chainCode,output:"Three named teaching tasks print their labels in dependency order. No data is loaded.",steps:["Parsing constructs task definitions; it does not run their Python bodies.","One triggered DAG run creates task instances for extract, transform and load.","Each downstream task waits for upstream success, then for execution capacity."],
    decision:q("A load must never start before extraction and transformation succeed. What expresses that rule?",["Put three function definitions in file order","extract >> transform >> load","Name the load task last alphabetically"],1,"Dependencies, not source-file position, express the required order."),hint:"Airflow needs graph edges, not the visual order of Python definitions.",solution:"Declare extract >> transform >> load with the default all_success trigger rule. Monitor actual task instances; eligibility does not guarantee an immediate start.",
    interview:["What problem does Airflow solve?","It coordinates scheduled or triggered workflows and tracks task dependencies, attempts and outcomes. It can call processing systems rather than replacing their compute engines.","Where would Spark fit in an Airflow-managed pipeline?"],mistakes:[["Treating Airflow as the data warehouse","Orchestration state is not your analytical dataset.","Store data in an appropriate external system.","Store sales rows in orchestration metadata","Store sales externally; orchestrate the load"],["Assuming file order controls execution","Independent tasks can run concurrently.","Declare the necessary edges.","Define load after extract","extract >> load"]],quiz:[q("What is tracked separately for each run?",["A task instance","Only the Python file name","Only the dashboard theme"],0,"Each task has execution state for a particular DAG run."),q("Where should a large distributed aggregation normally run?",["At DAG import time","In an appropriate processing system coordinated by a task","Inside a metadata field"],1,"Keep parsing lightweight and use suitable compute.")],doc:"core-concepts/overview.html"},
  {id:"dags-dependencies",title:"DAGs, Tasks & Dependencies",visual:"execution",execution:"dependencies",
    idea:"A DAG is a directed graph without cycles. Tasks are nodes; dependencies are edges. A >> [B, C] creates a fan-out, and [B, C] >> D joins their paths.",why:"Explicit dependencies allow independent checks to overlap while preventing a load from racing its prerequisites.",remember:"Under all_success, both parents must succeed. Parallel eligibility is not guaranteed simultaneous execution.",takeaway:"Read the arrows to predict eligibility; use capacity and task states to explain actual execution.",code:forkCode,output:"validate and enrich may overlap after extract. load waits for both.",steps:["extract is the only root of this graph.","After extract succeeds, validate and enrich have no dependency on each other.","load becomes eligible only when both parents succeed."],
    decision:q("validate succeeded but enrich is still running. Can load run with all_success?",["Yes, one parent is enough","No, enrich must also succeed","Only if load was defined first"],1,"The join requires every direct parent to succeed."),hint:"Count the incoming arrows to load.",solution:"Keep [validate, enrich] >> load. With all_success, load waits until both have succeeded. Do not add a cycle back to extract.",interview:["DAG versus task: what is the distinction?","The DAG defines workflow structure and policies; a task defines a unit of work. A DAG run and its task instances are the executions of those definitions.","Would adding validate >> enrich change which work can overlap?"],mistakes:[["Hidden dependencies","A task may start before the data it needs exists.","Declare the required relationship.","extract and load have no edge","extract >> load"],["Creating a cycle","A directed cycle cannot establish a valid execution order.","Model repeated work as separate runs or explicit bounded processing.","A >> B >> A","A >> B within each DAG run"]],quiz:[q("Which expression creates two children of A?",["A >> [B, C]","A >> B >> C","[A, B] >> C"],0,"B and C both depend directly on A."),q("Which statement is safe about sibling tasks?",["They always start together","They may run concurrently if capacity permits","The alphabetical first must finish first"],1,"Edges and resource limits determine the opportunities for concurrency.")],doc:"core-concepts/dags.html"},
  {id:"architecture",title:"Airflow Architecture",visual:"architecture",idea:"DAG processing discovers workflow structure. The Scheduler evaluates run and task eligibility; the Executor dispatches execution. Task processes do the work, while the metadata database records orchestration state.",why:"Knowing each responsibility helps distinguish a parsing problem, a scheduling delay and a worker failure.",remember:"In Airflow 3, task code uses the Task SDK/execution API rather than direct metadata-database access. The API server serves the UI/API; deployment details depend on the executor.",takeaway:"Scheduler decides; executor dispatches; task execution performs work; state and logs explain what happened.",code:"# Responsibilities, not a deployment configuration\nroles = {\n    'dag_processor': 'parse and serialize definitions',\n    'scheduler': 'evaluate eligibility',\n    'executor': 'dispatch execution',\n    'task_process': 'run task code',\n    'metadata_db': 'persist orchestration state',\n    'api_server_ui': 'inspect and manage runs',\n}",codeKind:"Configuration fragment",output:"This dictionary documents roles; it does not start Airflow services.",steps:["A DAG processor parses definitions and makes their structure available.","The scheduler and configured executor coordinate eligible work.","Inspect runs and logs through the UI/API; task execution and database state are different responsibilities."],decision:q("A task is queued but no execution slot is available. Which explanation is most plausible?",["The Python body has already finished","Dispatch/execution capacity is delaying it","DAGs cannot have dependencies"],1,"Queued work has been submitted but has not started executing."),hint:"Separate deciding to run from obtaining capacity to execute.",solution:"Inspect executor/worker health, queues, pools and concurrency limits. Do not rewrite task business logic before confirming that it has started.",interview:["Does the scheduler execute every task’s Python body?","It evaluates scheduling and submits work through the executor. Where code executes depends on the executor and deployment; the task execution process performs the task body.","Which component would you inspect when a DAG fails to parse?"],mistakes:[["Reading the metadata DB directly from tasks","It bypasses the Airflow 3 task interface and security boundary.","Use supported Task SDK APIs.","Direct ORM queries from task code","Use airflow.sdk and supported context APIs"],["Using worker logs to diagnose every missing DAG","The DAG may not have parsed at all.","Check import/parsing errors first.","Wait for a nonexistent task log","Inspect DAG processor/import errors"]],quiz:[q("Who evaluates task eligibility?",["The scheduler","A sales database row","A browser tooltip"],0,"Scheduling is a control-plane responsibility."),q("What belongs in metadata storage?",["Every raw sales file","DAG/task run state","A replacement for object storage"],1,"Metadata describes orchestration rather than holding the bulk dataset.")],doc:"public-airflow-interface.html"},
  {id:"scheduling",title:"Scheduling & Data Intervals",visual:"schedule",idea:"A timetable determines when scheduled DAG runs become due and which data interval they represent. This lesson explicitly uses CronDataIntervalTimetable at 02:00 UTC.",why:"A run’s logical date is not necessarily the wall-clock time its tasks execute. Pipelines should process the intended interval even after a delay.",remember:"With this explicit interval timetable, [Jan 1 02:00, Jan 2 02:00) becomes due after Jan 2 02:00. A bare cron in Airflow 3 can use trigger-style semantics; do not assume the two are identical.",takeaway:"Specify timezone and timetable; distinguish interval boundaries, logical date and actual start time.",code:intervalCode,output:"For a scheduled run due Jan 2 at 02:00 UTC: start Jan 1 02:00, end Jan 2 02:00. Actual execution can be later.",steps:["The explicit timetable removes ambiguity from cron defaults.","The interval closes at the next 02:00 boundary; its start identifies the logical interval.","Use interval context for the data selection, not datetime.now()."],decision:q("Which interval does the run due Jan 3 at 02:00 UTC cover in this example?",["Jan 3 02:00 → Jan 4 02:00","Jan 2 02:00 → Jan 3 02:00","All of January"],1,"The interval-based run is scheduled after its interval ends."),hint:"Look one boundary back from the due time.",solution:"Use [2026-01-02 02:00 UTC, 2026-01-03 02:00 UTC). Filter data with inclusive start and exclusive end. This is not a midnight calendar-day interval.",interview:["How do logical date and execution time differ?","For this interval timetable, logical date corresponds to interval start, while the run is due after interval end and tasks may start later. Use data-interval context to select records.","What changes if the business needs midnight-to-midnight sales processed at 02:00?"],mistakes:[["Using now() to select data","A rerun can process a different day.","Use the run’s intended interval.","Read today's partition","Read the interval-specific partition"],["Ignoring the timezone","The same clock time can mean different boundaries.","Use an explicit timezone and document daylight-saving behavior.","Daily at 2 with no timezone contract","02:00 UTC with explicit timetable"]],quiz:[q("Is a due time a guaranteed task start?",["Yes","No, execution capacity may delay it","Only for Python"],1,"Scheduling and execution availability are different."),q("Which boundary convention avoids double-reading adjacent intervals?",["Include both ends","Inclusive start, exclusive end","Ignore timestamps"],1,"A boundary record belongs to the next interval, not both.")],doc:"authoring-and-scheduling/timetable.html",setup:"Trigger as a scheduled interval run in Airflow 3.1. This example assumes data_interval_start/end exist; manual or event-triggered runs can require explicit input parameters."},
  {id:"catchup-backfill",title:"Catchup & Backfill",visual:"catchup",idea:"Catchup lets the scheduler create missing eligible scheduled runs. Backfill explicitly requests historical runs over a selected range with chosen reprocessing and concurrency policies.",why:"Reprocessing January sales should target January’s data, not reread today for every historical run.",remember:"catchup=False is not a deletion policy and does not prevent an explicitly requested backfill. Clear/rerun actions and backfills can repeat side effects.",takeaway:"Historical runs need interval-aware, idempotent tasks and controlled concurrency.",code:intervalCode.replace('catchup=False','catchup=True').replace('dataprep_daily_sales','dataprep_catchup'),output:"When enabled after several closed intervals, catchup=True can create their missing runs. Existing runs and scheduler limits affect the exact set and timing.",steps:["Choose fixed start_date and an explicit interval timetable.","Catchup considers missing eligible historical intervals rather than just the latest one.","For a controlled reprocess, select the range and reprocessing policy in Backfill; inspect a dry run before creating it."],decision:q("You need to intentionally recompute three historical intervals after a logic fix. What should you do?",["Change every task to use today's date","Plan a bounded backfill with a reprocessing policy and safe writes","Increase retries forever"],1,"A bounded backfill and idempotent writes control the scope and repeated effects."),hint:"This is deliberate historical reprocessing, not a retry of one failed attempt.",solution:"Review the three interval boundaries, choose the backfill reprocessing policy, check a dry run, limit active runs and reconcile outputs. Make tasks address their interval’s data.",interview:["Catchup versus backfill?","Catchup is scheduler behavior for missing eligible scheduled runs; backfill is an explicit historical request with a range and policy. Both require interval-aware tasks and safe repeated execution.","How would you avoid flooding an external API during reprocessing?"],mistakes:[["Catchup tasks always read the latest file","Historical run labels no longer match the processed data.","Derive inputs from the intended interval.","Every run reads latest.csv","Each run reads its interval-specific reference"],["Unlimited historical concurrency","Many runs can overload a service.","Bound active runs and protect shared resources with pools.","Launch the entire history without limits","Preview range; cap concurrency; monitor results"]],quiz:[q("Does catchup=False forbid explicit historical backfills?",["Yes","No","Only in UTC"],1,"A deliberately requested backfill is separate from automatic catchup."),q("A historical rerun duplicates warehouse rows. What property is missing?",["Idempotency","A bigger font","Another DAG name"],0,"Repeated processing must not duplicate business effects.")],doc:"core-concepts/backfill.html"},
  {id:"taskflow",title:"TaskFlow & Operators",visual:"execution",execution:"chain",idea:"TaskFlow wraps Python functions as tasks. Calling a decorated function while defining a DAG creates a task/output reference, not the final runtime result. Operators provide packaged work such as calling external services.",why:"Data dependencies can be expressed through TaskFlow arguments while provider operators integrate established systems.",remember:"Use airflow.sdk for DAG authoring in Airflow 3. Provider operators need their compatible provider packages; do not assume every operator ships in core.",takeaway:"Decorated calls build the graph; task bodies run later in task instances.",code:wrap("taskflow",`@task\ndef extract():\n    return 150\n\n@task\ndef transform(amount: int):\n    return amount + 20\n\n@task\ndef load(amount: int):\n    print(amount)\n\nload(transform(extract()))`),output:"The final task prints 170. The scalar values are small teaching XCom payloads.",steps:["extract() creates a reference to an eventual task result.","Passing it to transform establishes a data dependency.","Runtime results flow through XCom; arbitrary large tables should not be returned this way."],decision:q("At DAG parsing time, what is transform(extract()) building?",["The final integer immediately","Task definitions and an output dependency","A database transaction"],1,"The decorated call describes future task execution and data flow."),hint:"Ask whether the worker has started yet.",solution:"Keep processing inside @task bodies. Pass task output references as inputs for small values; instantiate the @dag factory so Airflow can discover the DAG.",interview:["When would you mix TaskFlow and operators?","Use TaskFlow for small custom Python work and compatible provider operators for packaged integrations. Connect their dependencies explicitly and check what data is passed.","Why is a heavy API call at the top level of a DAG file a problem?"],mistakes:[["Heavy work during DAG parsing","Repeated parsing can hammer services and slow discovery.","Move runtime work into tasks.","rows = fetch_all_sales() at module level","@task def extract(): return a small storage reference"],["Returning a huge DataFrame","It may become an unsuitable XCom payload.","Store the bulk data externally.","return huge_dataframe","return storage_uri"]],quiz:[q("Which import is the authoring baseline here?",["from airflow.sdk import dag, task","A legacy execution_date variable","Direct metadata ORM access"],0,"The lesson uses the Airflow 3 Task SDK."),q("Does changing function definition order replace dependencies?",["Yes","No","Only for @task"],1,"The dependency graph controls eligibility.")],doc:"tutorial/taskflow.html"},
  {id:"task-lifecycle",title:"Task Lifecycle",visual:"execution",execution:"chain",idea:"A task instance has state within a DAG run. A normal path is none → scheduled → queued → running → success; other paths include failure, retry, skip or sensor rescheduling.",why:"A queued task has not begun its body, so debugging its business code may be premature.",remember:"Task definition, task instance and attempt are different concepts. One task instance may make several attempts.",takeaway:"Use the current state to identify which part of the execution path needs investigation.",code:chainCode,output:"Watch Execution traces state changes for one run, not every possible state or exact executor timing.",steps:["Scheduled indicates scheduling eligibility; queued indicates submission for execution.","Running means task code is executing.","Success can make downstream tasks eligible, subject to their trigger rules."],decision:q("A task has been queued for ten minutes. What should you inspect before its Python traceback?",["Worker/executor capacity and queue health","The completed output rows","The next task's success log"],0,"The task may not have started, so investigate dispatch and execution availability."),hint:"Queued and running are different states.",solution:"Check executor/worker availability, pools and concurrency. Identify the DAG run and task instance; do not mark success merely to clear the queue.",interview:["What is a task instance?","It is a particular task’s execution within a DAG run, with its own state and attempts. A task definition is reusable across runs; a retry is another attempt of that instance.","How do you distinguish a queue delay from a slow running task?"],mistakes:[["Equating queued with running","It points debugging at code that may not be executing.","Check state transitions and execution capacity.","Queued means processing data","Queued means waiting to execute"],["Manually marking success without checking outputs","Downstream work can consume absent data.","Verify effects before changing state.","Mark success to make the DAG green","Validate outputs; fix and rerun appropriately"]],quiz:[q("After success, does a dependent task necessarily start immediately?",["Yes","No, other dependencies and capacity still matter","Only if it has no code"],1,"Success satisfies a dependency, not all scheduling conditions."),q("What does none mean in this teaching trace?",["No task state has been set yet","Task failed permanently","An empty business dataset"],0,"The UI labels unset/none distinctly from failed.")],doc:"core-concepts/tasks.html"},
  {id:"retries",title:"Failures & Retries",visual:"execution",execution:"retries",idea:"Retries repeat a failed task attempt according to policy. With retries=1, a task can make its initial attempt plus one additional attempt. During the delay it is up_for_retry.",why:"Transient outages can recover automatically, but repeated writes must not duplicate data.",remember:"A task waiting for retry has not succeeded. Under all_success, downstream work waits; an exhausted upstream failure can lead to upstream_failed downstream.",takeaway:"Bound retries, allow a sensible delay and make repeated effects safe.",code:retryCode,output:"The teaching transform fails attempt 1, waits five minutes, then succeeds on attempt 2. The real example delay is not shortened by the visual simulation.",steps:["extract succeeds and transform starts its first attempt.","The deliberate transient error enters up_for_retry; load remains waiting.","After the delay a new attempt runs. Compare success recovery with exhausted failure in the visual."],decision:q("With retries=2, what is the maximum number of attempts from one normal initial execution?",["2","3","Unlimited"],1,"The initial attempt plus two retries makes three attempts."),hint:"Retries are additional attempts, not the initial attempt.",solution:"Count initial attempt + retries. Choose a delay and backoff appropriate to the dependency; stop retrying deterministic validation errors and investigate their cause.",interview:["What happens when a task fails?","Airflow applies its retry policy. An eligible retry waits, then executes another attempt; exhausted failure is terminal until explicit recovery. Downstream trigger rules decide whether other tasks can proceed.","What if attempt 1 committed a write before its process crashed?"],mistakes:[["Retrying unsafe inserts","A partially completed attempt can duplicate data.","Use event keys, upserts or atomic interval replacement.","INSERT duplicates on every attempt","Idempotent write keyed to business identity"],["Retrying invalid data forever","More attempts do not fix a deterministic schema error.","Fail clearly, inspect evidence and repair the input/logic.","Unlimited retry for missing column","Bounded policy plus actionable validation error"]],quiz:[q("Which state represents a failed attempt with another automatic attempt remaining?",["success","up_for_retry","skipped"],1,"The instance is waiting for its next eligible attempt."),q("If transform exhausts retries, what happens to all_success load?",["It must run anyway","It cannot satisfy the upstream success requirement","It becomes a new DAG definition"],1,"It may be marked upstream_failed without executing.")],doc:"core-concepts/tasks.html"},
  {id:"trigger-rules",title:"Branching & Trigger Rules",visual:"execution",execution:"branching",idea:"Trigger rules describe which upstream states permit a task to run. all_success is the default. After a branch, a join often needs none_failed_min_one_success so a skipped alternative does not block the selected path.",why:"A deliberate skipped path is not the same as a failed data-quality check.",remember:"all_done does not mean all_success. A successful cleanup leaf can affect DAG-run status, so do not use a green cleanup task as proof the pipeline succeeded.",takeaway:"Choose a join rule for the intended success, skip and failure semantics.",code:wrap("branching",`@task.branch\ndef choose():\n    return "load"\n\n@task\ndef load():\n    print("Load chosen")\n\n@task\ndef no_data():\n    print("No data path")\n\n@task(trigger_rule="none_failed_min_one_success")\ndef join():\n    print("Selected path completed")\n\nchoice = choose()\na, b, end = load(), no_data(), join()\nchoice >> [a, b]\n[a, b] >> end`),output:"load succeeds; no_data is skipped; join accepts success + skipped.",steps:["The branch returns the chosen downstream task_id.","The unselected direct path is skipped.","The join waits for the required terminal states and checks its trigger rule."],decision:q("The parents of a join are success and skipped. Which rule fits a successful selected branch?",["all_success","none_failed_min_one_success","Require both to fail"],1,"No parent failed and at least one succeeded."),hint:"A skipped alternative cannot satisfy all_success.",solution:"Use none_failed_min_one_success for this join. Keep failure propagation intentional; do not substitute all_done when success is required.",interview:["Why can a join be skipped after branching?","With all_success, a skipped upstream path does not satisfy the join. Use the trigger rule matching the branch semantics and test success, all-skipped and failure cases.","Why might an all_done cleanup leaf make run status misleading?"],mistakes:[["Using all_done as proof of valid data","It permits downstream work after failures.","Separate cleanup from data publication requirements.","Publish with all_done","Publish only when validation succeeds"],["Requiring every branch to succeed","Unselected paths intentionally skip.","Use a branch-aware join rule.","join: all_success after alternative paths","join: none_failed_min_one_success"]],quiz:[q("For none_failed_min_one_success, are success + failed acceptable?",["Yes","No","Only when retries=0"],1,"A failed parent violates the rule."),q("Are skipped + skipped enough for that same rule?",["Yes","No","They count as two successes"],1,"At least one successful parent is required.")],doc:"core-concepts/dags.html"},
  {id:"xcom",title:"XCom & Task Communication",visual:"xcom",idea:"XCom communicates small values between task instances. TaskFlow can automatically pass returned values. For a large dataset, write to external storage and pass a path or other compact reference.",why:"Tasks can run on different workers. Local memory and a local path are not shared storage contracts.",remember:"A URI is only useful if downstream tasks have access and the object exists. Keep credentials out of XCom; specialized backends do not remove the need for clear data contracts.",takeaway:"Orchestrate bulk data by reference; keep task messages small and scoped to the run.",code:wrap("xcom",`@task\ndef manifest():\n    # Teaching reference only; this example does not create the object.\n    return {"uri": "s3://example-data/sales/2026-01-01.parquet", "rows": 2}\n\n@task\ndef inspect_reference(info: dict):\n    print(info["uri"], info["rows"])\n\ninspect_reference(manifest())`),output:"A small dictionary with a URI and row count passes to the downstream task. No object is read or written.",steps:["A real producer writes bulk data to durable external storage first.","The task returns a small reference, stored/transferred using XCom semantics.","The consumer resolves that reference with its own authorized access."],decision:q("A task produces 5 GB of sales data. What should normally be passed to its consumer?",["The entire DataFrame via XCom","A durable storage reference plus small metadata","A worker-local variable name"],1,"The data remains outside orchestration metadata; both tasks need a shared storage contract."),hint:"The next task may run on another machine.",solution:"Write the dataset durably, then pass its URI and compact validation metadata. The consumer reads the URI using an approved Connection; do not send credentials in the payload.",interview:["Why avoid large XCom payloads?","They couple orchestration communication to bulk data storage and transfer. Use durable datasets and references; keep messages small and validate consumer access and lifecycle.","What if a producer returns a path before its upload is complete?"],mistakes:[["Passing local filenames as shared data","Another worker may not have that file.","Use shared durable storage and explicit access.","/tmp/sales.csv on worker A","A durable object URI readable by worker B"],["Sending secrets in returned values","Returned payloads can be exposed to orchestration users or logs.","Resolve secrets through Connections/secrets backends.","return password","return a non-secret data reference"]],quiz:[q("What can TaskFlow do with a small returned value?",["Pass it downstream through XCom","Make it global across every DAG forever","Automatically upload all files"],0,"TaskFlow wires task outputs and dependencies."),q("Does passing an object URI guarantee the object exists?",["Yes","No","Only for Parquet"],1,"The producer must complete and validate its write before publishing the reference.")],doc:"core-concepts/xcoms.html"},
  {id:"sensors",title:"Sensors & Waiting",visual:"execution",execution:"sensors",idea:"A Sensor waits for a condition, such as an upstream file being ready. Poke mode holds a worker slot; reschedule mode releases it between checks. Compatible deferrable operators use a triggerer while waiting.",why:"Hundreds of idle waiting tasks should not unnecessarily occupy all execution workers.",remember:"Rescheduling and deferral are different mechanisms. @task.sensor supports poke/reschedule here; a normal TaskFlow function does not become deferrable just by setting a flag.",takeaway:"Match waiting behavior to check frequency, available operators and timeout requirements.",code:wrap("sensor",`@task.sensor(poke_interval=60, timeout=3600, mode="reschedule")\ndef wait_file() -> PokeReturnValue:\n    # Local teaching stand-in: set Variable sales_file_ready to true.\n    ready = Variable.get("sales_file_ready", default="false") == "true"\n    return PokeReturnValue(is_done=ready)\n\n@task\ndef load():\n    print("Readiness confirmed; validate contents separately")\n\nwait_file() >> load()`,`from airflow.sdk import PokeReturnValue, Variable`),output:"The sensor checks a non-secret teaching Variable every minute, up to its timeout; downstream load waits for success.",steps:["A false check is not success: reschedule releases the worker slot.","After the next check time, execution capacity is needed again.","A true readiness condition lets the sensor succeed; content quality still needs its own validation."],decision:q("A file may arrive in an hour and checking once a minute is sufficient. What is reasonable?",["Busy-loop with no timeout","Reschedule-mode sensor, or a supported deferrable sensor","Mark success before arrival"],1,"Both can avoid tying up a worker during the wait when used with their required infrastructure."),hint:"Waiting is not the same as continuously performing useful CPU work.",solution:"Set an appropriate poke interval and timeout. Use reschedule for periodic checks or a provider’s compatible deferrable sensor with a triggerer. Verify the ready condition rather than merely sleeping a fixed hour.",interview:["Sensor poke, reschedule and deferral: how do they differ?","Poke holds a worker between checks; reschedule releases it until a later check. Deferral offloads waiting to a trigger and triggerer before resuming on a worker. Operator support and deployment requirements differ.","Does file existence alone prove its data is complete and valid?"],mistakes:[["Unbounded waits","A pipeline can remain stuck indefinitely.","Define a meaningful timeout and escalation.","Wait forever","Bounded waiting with actionable timeout"],["Assuming every task supports deferral","Ordinary TaskFlow code lacks that operator lifecycle.","Use an explicitly supported deferrable operator.","Set deferrable on arbitrary Python logic","Use a supported sensor/operator and triggerer"]],quiz:[q("Which state represents a sensor waiting between rescheduled checks?",["up_for_reschedule","success","upstream_failed"],0,"No worker should be occupied simply waiting between checks in this mode."),q("What component supports deferrable waiting?",["The triggerer","A bigger XCom message","A database table named sensor"],0,"The triggerer runs asynchronous triggers.")],doc:"authoring-and-scheduling/deferring.html"},
  {id:"configuration",title:"Variables, Params & Connections",visual:"config",idea:"Variables hold shared configuration; Params describe run inputs with validation; Connections identify external services and credentials. Resolve secrets through the configured secret-management path, not source code.",why:"Configuration changes and secret rotation should not require embedding passwords in a DAG file.",remember:"Fetch runtime configuration inside tasks when possible. Do not log credentials or use untrusted Params to build unsafe shell commands or SQL.",takeaway:"Separate shared settings, run-specific inputs and service credentials.",code:wrap("configuration",`@task\ndef inspect_config():\n    context = get_current_context()\n    region = context["params"]["region"]\n    mode = Variable.get("sales_mode", default="daily")\n    warehouse = Connection.get("warehouse")\n    # Never print the connection object, password or URI.\n    print(region, mode)\n\ninspect_config()`,`from airflow.sdk import Connection, Variable, get_current_context, Param`).replace('catchup=False,','catchup=False,\n    params={"region": Param("IN", type="string", enum=["IN", "US"])},'),output:"The task reads validated region, a shared mode and the configured warehouse Connection. Configure that Connection before running; no database query is issued.",steps:["A Param describes the allowed region input.","A Variable supplies shared, non-secret mode configuration.","A Connection resolves external-service configuration without hardcoded credentials."],decision:q("Where should the warehouse password live?",["In a committed Python string","In the configured Connection/secrets mechanism","In the run's printable region Param"],1,"Connections and secret backends provide the intended credential path; access should remain least-privileged."),hint:"Treat secrets differently from ordinary run input.",solution:"Configure a warehouse Connection through the deployment’s secret-management mechanism. Reference its ID from the task or provider hook; do not print it or commit real credentials.",interview:["How do Params differ from Variables?","Params are validated run-input definitions; Variables are shared key/value configuration. Connections describe external service access and should be backed by an appropriate secret policy.","Why can reading Variables at module import time be expensive?"],mistakes:[["Hardcoding credentials","Source control and logs become secret-distribution channels.","Use a Connection and secret backend.","password = '<actual secret>'","Connection.get('warehouse') at task runtime"],["Trusting input as executable code","An allowed input field is not permission to execute arbitrary code.","Validate inputs and use safe parameterized interfaces.","Concatenate run input into SQL","Validated input + parameterized query"]],quiz:[q("Which fits a region chosen for one run?",["A validated Param","An embedded database password","The task's success state"],0,"Params define run inputs and validation."),q("Should connection objects be printed for debugging?",["Yes, always","No, they may contain sensitive details","Only during retries"],1,"Log safe identifiers and error context, not secrets.")],doc:"public-airflow-interface.html"},
  {id:"dynamic-mapping",title:"Dynamic Task Mapping",visual:"execution",execution:"mapping",idea:"Dynamic Task Mapping creates task instances from a runtime collection. A two-file list can produce process[0] and process[1] without writing a different task definition for every file.",why:"The number of input partitions can vary by run while the workflow definition stays stable.",remember:"Mapping does not guarantee unlimited concurrency. Keep map inputs small and use pools, limits and sensible task granularity.",takeaway:"One mapped task definition can yield several task instances, each with its own index and state.",code:wrap("mapping",`@task\ndef list_files():\n    return ["part-a.parquet", "part-b.parquet"]\n\n@task\ndef process(path: str):\n    # Teaching stand-in: no file is read.\n    return f"would process {path}"\n\n@task\ndef summarize(results):\n    print(list(results))\n\nparts = process.expand(path=list_files())\nsummarize(parts)`),output:"Two mapped process instances produce two short messages; summarize collects them after upstream success.",steps:["list_files returns a small two-item collection.","expand creates mapped indices 0 and 1 for this run.","The reducer waits for its mapped upstream work; execution order of siblings is not guaranteed."],decision:q("A run discovers two files. How many process task instances does this mapping create?",["One per file: two","A new DAG for every byte","Always exactly one"],0,"Each input item supplies the argument for one mapped instance."),hint:"Distinguish the reusable task definition from its map-indexed instances.",solution:"Use process.expand(path=list_files()) for the small list. Bound concurrency and validate input size; use a reducer only after the relevant mapped work completes.",interview:["Dynamic task mapping versus a parse-time loop?","A parse-time loop builds a graph from values known during parsing. Mapping expands task instances from runtime data. It fits variable work lists but still requires limits and appropriate granularity.","Why is mapping one task per tiny record often inefficient?"],mistakes:[["Unlimited tiny tasks","Scheduler overhead can outweigh useful work.","Batch work into meaningful chunks.","One task for every byte","One task per useful file or partition"],["Returning massive mapping inputs","Huge lists stress communication and scheduling.","Keep manifests bounded and partition processing sensibly.","Millions of XCom items without limits","Bounded manifest and explicit limits"]],quiz:[q("Must mapped siblings finish in index order?",["Yes","No","Only if their names match"],1,"Capacity and runtime behavior can produce a different completion order."),q("Mapping determines what?",["A guaranteed number of worker machines","Task instances based on the input collection","A bypass for dependency rules"],1,"Mapping defines instances, not unlimited resources.")],doc:"authoring-and-scheduling/dynamic-task-mapping.html"},
  {id:"monitoring",title:"Monitoring & Debugging",visual:"monitoring",idea:"Debug a specific task instance and attempt: inspect state, logs, inputs, configuration and upstream evidence. A failure message is evidence to investigate, not a reason to blindly rerun everything.",why:"An authentication failure and a missing-column error need different repairs; retries cannot solve every cause.",remember:"Check DAG parse errors before searching for task logs if the task was never discovered. Redact credentials and sensitive data from logs.",takeaway:"State → attempt logs → cause → safe fix → controlled rerun → output validation.",code:"# Inside a task: validate explicitly and log safe context.\nimport logging\n\ndef validate_record(record):\n    if 'amount' not in record:\n        raise ValueError('Required column amount missing')\n    logging.info('Sales record schema validated')\n    return record",codeKind:"Task fragment",output:"A record without amount raises a clear ValueError. No Airflow task is created by this standalone function fragment.",steps:["Locate the failing run, task and attempt.","Read the error and confirm its input schema; do not log the raw record if it contains sensitive data.","Repair the cause, consider already-written effects, then clear/rerun the intended scope and reconcile outputs."],decision:q("A task repeatedly raises 'Required column amount missing'. What should you do first?",["Increase retries to 100","Inspect the input schema and extraction contract","Mark downstream success"],1,"The error points to a deterministic contract mismatch rather than a transient timeout."),hint:"The task can reach the input, but its structure is wrong.",solution:"Compare the actual upstream schema with the expected contract, fix mapping/validation, and rerun the smallest safe scope. Check for partially written outputs before retrying.",interview:["How do you debug a failed Airflow task?","Identify the run and attempt, read the error, inspect relevant inputs/config/upstream state, classify transient versus deterministic cause, repair it and rerun safely. Validate business outputs, not just a green state.","When would clearing only one task be unsafe for downstream outputs?"],mistakes:[["Ignoring the failing attempt log","The real failure cause stays hidden.","Trace the exact instance and attempt.","Retry the whole DAG first","Inspect state and attempt evidence first"],["Logging credentials or raw sensitive records","Debugging becomes a data exposure risk.","Log safe context and sanitized errors.","print(connection)","Log connection ID and redacted failure type"]],quiz:[q("Which error is unlikely to be fixed by a delay alone?",["A temporary network timeout","A required column absent from every input","A brief service outage"],1,"The schema contract needs repair."),q("After a rerun turns green, what remains to check?",["Output correctness and duplicate effects","Nothing","Only the UI color"],0,"Task state is not a full business-data validation.")],doc:"administration-and-deployment/logging-monitoring/logging-tasks.html"},
  {id:"production",title:"Production Practices",visual:"production",idea:"Reliable orchestration uses idempotent effects, interval-specific inputs, clear dependencies, bounded retries, safe credentials and observable outcomes. Task size should balance useful isolation against scheduling overhead.",why:"Retries and historical runs are normal. A duplicate insert or a today-based input can corrupt results while tasks appear successful.",remember:"Airflow does not automatically provide exactly-once external writes. Atomic commits, deduplication keys and target-system semantics matter.",takeaway:"Design for repeated execution and partial failure, then test the business outputs.",code:"# Target-system SQL pattern, shown as Python text; not executed here.\n# Configure access through an Airflow Connection.\nupsert = '''\nINSERT INTO sales (order_id, amount) VALUES (%s, %s)\nON CONFLICT (order_id) DO UPDATE SET amount = EXCLUDED.amount;\n'''\n# Requires a UNIQUE/PRIMARY KEY on order_id and the intended\n# business rule for corrections. Bind parameters; commit atomically.",codeKind:"Task fragment",output:"The illustrated PostgreSQL upsert targets one business key. Actual execution, transactions and error handling belong in the database task implementation.",steps:["Choose source identity and data interval so a retry addresses the same work.","Use target-supported atomic writes or governed upserts; do not blindly append.","Measure outputs and protect external resources with pools and concurrency limits."],decision:q("An insert committed before the worker crashed. What makes a retry safe?",["Insert identical rows again","A business-key-aware idempotent write contract","Assume Airflow rolled back the remote system"],1,"Airflow cannot automatically undo a remote commit; the task must handle repeated effects."),hint:"Think about the state of the external target, not just the task state.",solution:"Use the intended event key with an atomic upsert or replace the intended interval safely. Validate corrections and reconcile counts/totals; coordinate concurrent runs that might write the same target.",interview:["What does idempotency mean for an Airflow task?","Repeating the task for the same intended input does not multiply its business effect. It requires target-aware writes and stable inputs, not merely setting retries or catchup=False.","How would you handle a retry racing another backfill for the same partition?"],mistakes:[["Blind append on every attempt","A retry duplicates already committed events.","Use a governed deduplication/upsert strategy.","Append identical order on every attempt","Unique business key plus safe update semantics"],["Heavy I/O at DAG import time","Parsing is repeated and should remain lightweight.","Move heavy I/O to task runtime or the right compute service.","Download a dataset during import","Task submits/monitors the processing job"]],quiz:[q("Does retries=0 guarantee exactly-once writes?",["Yes","No","Only with catchup=False"],1,"Manual reruns and partial failures can still repeat or leave effects."),q("What is a pool useful for?",["Protecting limited shared service capacity","Storing all sales files","Eliminating all task failures"],0,"Pools can constrain concurrent work against a scarce resource.")],doc:"best-practices.html"},
  {id:"etl-review",title:"Build & Review a Sales DAG",visual:"execution",execution:"etl",idea:"Apply the fundamentals to extract → validate → transform → load → quality check. Each edge protects an explicit contract; each retry must respect the target’s write semantics.",why:"A complete interview answer explains not just the graph but its schedule, failure policy, data movement and recovery behavior.",remember:"The sample uses tiny in-memory teaching values and a print-only load stand-in. It does not ingest an API or write a warehouse.",takeaway:"Explain what each task guarantees, what makes the next task eligible, and how you recover without corrupting data.",code:finalCode,output:"Two valid teaching orders sum to 150. load prints 'Would publish total=150'; quality_check validates that fixture total.",steps:["Extract two tiny orders and validate identity and positive amounts.","Transform to total 150; the load stand-in prints the value and returns it.","The final check verifies the teaching fixture. In production use durable references and a real idempotent load contract."],decision:q("Where should a data-quality gate that must prevent bad loads sit?",["Only after every downstream report","Upstream of the load, with a required-success dependency","Outside the dependency graph"],1,"A preventative validation must succeed before the load is eligible."),hint:"An after-load check detects issues but cannot by itself prevent the earlier write.",solution:"Keep extract → validate → transform → load → quality_check. Add a real interval-aware input contract, safe warehouse writes and bounded transient retries in production. Post-load checks reconcile outputs; pre-load checks prevent known bad inputs.",interview:["Design a daily sales ETL DAG and defend it.","State the data interval and timezone, define extraction and validation contracts, pass durable data references, run transformation in appropriate compute, perform idempotent loads and reconcile outputs. Explain retries, monitoring and controlled backfills.","How would an invalid record and a temporary warehouse outage follow different recovery paths?"],mistakes:[["Pretending a toy example is production ingestion","It omits credentials, durable storage and real writes.","Label stand-ins and identify their production contracts.","Printing a total called a warehouse load","Explicit print-only stand-in; real load requires atomic target writes"],["Using success as the only acceptance check","Tasks may complete while producing duplicate or wrong data.","Include output and reconciliation checks.","Green task = correct dataset","Expected identities, counts and totals checked"]],quiz:[q("What total does the two-order teaching fixture produce?",["150","100","200"],0,"100 + 50 = 150."),q("What must change before calling the sample a real warehouse pipeline?",["Only its task colors","Implement durable input/output, credentials and safe write contracts","Rename quality_check"],1,"The teaching stand-ins are not external ingestion or storage.")],doc:"tutorial/taskflow.html"},
];

export const airflowLessons:AirflowLesson[]=specs.map(s=>({id:s.id,title:s.title,minutes:s.id==="introduction"?15:25,description:s.takeaway,concepts:[["What is it?",s.idea],["Why it matters",s.why],["Remember",s.remember]],flow:s.steps,example:{code:s.code,output:s.output,walkthrough:s.steps},practice:{task:s.decision.question,hint:s.hint,solution:s.solution,output:s.decision.explanation},interview:[{question:s.interview[0],answer:s.interview[1],followup:s.interview[2]},{question:s.decision.question,answer:s.solution,followup:"What would you inspect in a real Airflow run to validate this answer?"}],mistakes:s.mistakes.map(([title,why,better,before,after])=>({title,why,better,before,after})),quiz:s.quiz,visual:s.visual,execution:s.execution,takeaway:s.takeaway,decision:s.decision,resource:airflowDocs+s.doc,setup:s.setup??"Airflow 3.1 Task SDK baseline. Python DAG examples require a separately configured Airflow environment and compatible standard provider. This website does not run Airflow or execute your draft.",codeKind:s.codeKind??"Complete teaching DAG"}));
export const airflowById=Object.fromEntries(airflowLessons.map(lesson=>[lesson.id,lesson]));
